def test_parse_transcript_log_strips_fields_and_skips_blank_lines_and_comments():
    lines = ["", " \t\n", "  # ignored,not a day,1", " a , 1 , 0 ", " b, 2, ", " c, 3, 1"]
    assert parse_transcript_log(lines) == [
        {"id": "a", "day": 1, "flagged": False},
        {"id": "b", "day": 2, "flagged": None},
        {"id": "c", "day": 3, "flagged": True},
    ]


