def test_dedupe_transcripts_keeps_last_record_and_sorts_by_day_then_id():
    first = {"id": "a", "day": 3, "flagged": True}
    last = {"id": "a", "day": 2, "flagged": False}
    same_day = {"id": "b", "day": 2, "flagged": True}
    earlier = {"id": "z", "day": 1, "flagged": None}
    assert dedupe_transcripts([first, same_day, earlier, last]) == [earlier, last, same_day]


def test_daily_flag_counts_fills_missing_days_and_ignores_out_of_range_events():
