def test_monitor_summary_uses_calendar_days_and_only_counts_nonempty_groups():
    groups = {
        "first": parse_transcript_log(["a,1,1", "b,3,1"]),
        "second": parse_transcript_log(["c,5,0"]),
        "empty": [],
    }
    assert monitor_summary(groups, 2) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 3) == {"rate": 0.667, "recent": 1, "groups": 2}
